SELECT assert_true(NOT has_function_privilege('service_role','fn_accrue_cash_hand_commissions(uuid)','EXECUTE'),'direct inner liability entry is private after the compatibility migration');
SELECT assert_true(has_function_privilege('service_role','credit_agent_commission_from_rake(uuid,uuid,numeric,text,uuid,text)','EXECUTE') AND has_function_privilege('service_role','calculate_cascading_commission(uuid,uuid,uuid,numeric,uuid,uuid)','EXECUTE'),'required legacy engine interfaces remain callable');
INSERT INTO rake_records(id,hand_id,club_id,rake_amount,created_at,metadata) VALUES(u(150),u(151),u(20),2,clock_timestamp(),jsonb_build_object('accounting_source_version',2,'union_id',u(20),'is_private',false)),(u(160),u(161),u(40),3,clock_timestamp(),jsonb_build_object('accounting_source_version',2,'union_id',NULL,'is_private',true));
INSERT INTO rake_attributions VALUES(u(152),u(150),u(151),u(12),u(10),2),(u(162),u(160),u(161),u(41),u(40),3);
SET ROLE service_role;
SELECT credit_agent_commission_from_rake(u(12),u(20),2,'rake_settlement',u(151));
SELECT calculate_cascading_commission(u(161));
RESET ROLE;
SELECT assert_true((SELECT status FROM accounting_cash_source_work WHERE rake_record_id=u(150))='accrued' AND EXISTS(SELECT 1 FROM rakeback_stats_applied WHERE rake_record_id=u(150) AND user_id=u(12) AND hands=1 AND rake=2),'legacy void call reaches canonical source statistics and acknowledgement');
SELECT assert_true((SELECT status FROM accounting_cash_source_work WHERE rake_record_id=u(160))='accrued' AND EXISTS(SELECT 1 FROM rakeback_stats_applied WHERE rake_record_id=u(160) AND user_id=u(41) AND hands=1 AND rake=3) AND EXISTS(SELECT 1 FROM accounting_period_recompute_requests WHERE club_id=u(40)),'agent-free player is a valid source through the cascading compatibility entry');
SELECT assert_true((SELECT count(*) FROM agent_commissions ac JOIN accounting_cash_rake_sources s ON s.id=ac.source_id WHERE s.rake_record_id=u(150))=3 AND NOT EXISTS(SELECT 1 FROM agent_commissions ac JOIN accounting_cash_rake_sources s ON s.id=ac.source_id WHERE s.rake_record_id=u(160)),'no-agent source preserves statistics without inventing an agent entitlement');
SELECT assert_true(calculate_cascading_commission(u(151))->>'duplicate'='true' AND (SELECT count(*) FROM accounting_cash_source_receipts WHERE rake_record_id=u(150))=1,'compatibility replay reaches the same once-only source receipt');
INSERT INTO rake_records(id,hand_id,club_id,rake_amount,created_at,metadata) VALUES(u(170),u(171),u(40),1,clock_timestamp(),jsonb_build_object('accounting_source_version',2,'union_id',NULL,'is_private',true));
SELECT assert_true(refuses('SELECT calculate_cascading_commission(u(171))','55000') AND NOT EXISTS(SELECT 1 FROM accounting_cash_source_work WHERE rake_record_id=u(170)),'legacy success-only caller receives an exception for incomplete evidence');
INSERT INTO rake_attributions VALUES(u(172),u(170),u(171),u(41),u(40),1);
SET test.fail_stats='true';
SELECT assert_true(refuses('SELECT credit_agent_commission_from_rake(u(41),u(40),1,''rake_settlement'',u(171))','55000') AND NOT EXISTS(SELECT 1 FROM accounting_cash_accrual_batches WHERE rake_record_id=u(170)),'void compatibility failure cannot retain partial accrual or pretend success');
SET test.fail_stats='false';
SELECT assert_true(refuses('SELECT calculate_cascading_commission(u(151),u(999))','23514') AND refuses('SELECT calculate_cascading_commission(u(151),NULL,u(999))','23514'),'compatibility arguments cannot claim another earning club or contributor');
SELECT assert_true(refuses('SELECT calculate_cascading_commission(u(151),NULL,NULL,0,u(160))','23514'),'hand and record identities cannot disagree');
SET test.engine='false';
SELECT assert_true(refuses('SELECT calculate_cascading_commission(u(151))','42501') AND refuses('SELECT credit_agent_commission_from_rake(u(12),u(10),2,''rake_settlement'',u(151))','42501'),'security-definer compatibility wrappers still enforce the original caller JWT guard');
SET test.engine='true';
DROP TRIGGER test_seed_source_bank ON rake_records;
